{
  "packet_id": "H6-T02-3",
  "claim_id": "C004",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C004.component",
    "value": "The proposed experiment assumes that export concurrency can be adjusted.",
    "scope": "Assumed experimental capability.",
    "provenance": {
      "refs": [
        {"source_id": "P003", "role": "SUPPORT"},
        {"source_id": "P002", "role": "CONTEXT"}
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P003 explicitly states the assumption; P002 identifies the proposed concurrency control."
    }
  },
  "signal_basis": {
    "component_id": "C004.signal_basis",
    "value": "With adequate telemetry, the operation prescribes changing canary concurrency from c0 to a lower c1 and holding it constant. The mapping explicitly assumes adjustability while acknowledging that this capability is unestablished.",
    "scope": "The proposed experiment's execution premise, rather than empirical verification of capability.",
    "provenance": {
      "refs": [
        {"source_id": "P009", "role": "SUPPORT"},
        {"source_id": "P003", "role": "SUPPORT"}
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The cited spans supply the prescribed manipulation and its explicit capability assumption and qualification."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C004.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "This claim describes an explicit experimental assumption; no unresolved empirical relation is needed to license that description."
    }
  },
  "rationale": "The claim accurately identifies a premise expressly adopted by the mapping and required by its prescribed concurrency step. It does not assert that adjustability has been demonstrated.",
  "uncertainty": "Actual adjustability remains unestablished in the packet, but that does not undermine the claim that the experiment assumes it.",
  "anomalies": []
}
